style.css:
:root {
  --bg-color: #ffd6ec;        /* nền hồng pastel */
  --text-color: #5a3a4a;
  --main-color: #ff9ecf;
  --secondary-color: #ffc2e2;
}

/* nền toàn bộ */
body {
  background-color: var(--bg-color) !important;
  color: var(--text-color);
}

/* khung code */
textarea, pre, code {
  background: #ffe4f2 !important;
  color: #5a3a4a;
  border-radius: 12px;
}

/* header / tiêu đề */
h1, h2, h3 {
  color: #ff8fc4;
}

/* viền box */
* {
  border-color: #ffb3d9 !important;
}

/* button */
button {
  background: var(--main-color);
  color: white;
  border-radius: 10px;
}
button:hover {
  background: var(--secondary-color);
}
